CREATE TABLE IF NOT EXISTS policy_documents(id TEXT PRIMARY KEY NOT NULL,code TEXT NOT NULL UNIQUE,title TEXT NOT NULL,category TEXT NOT NULL,classification TEXT NOT NULL,owner TEXT NOT NULL,reviewer TEXT NOT NULL,audience TEXT NOT NULL,review_frequency_days INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',current_version_id TEXT,next_review TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL,retired_by TEXT,retired_at TEXT);
CREATE INDEX IF NOT EXISTS policy_documents_status_review_idx ON policy_documents(status,next_review,category);
CREATE TABLE IF NOT EXISTS policy_versions(id TEXT PRIMARY KEY NOT NULL,policy_id TEXT NOT NULL,version_number INTEGER NOT NULL,summary TEXT NOT NULL,content TEXT NOT NULL,content_sha256 TEXT NOT NULL,control_refs_json TEXT NOT NULL,regulation_refs_json TEXT NOT NULL,risk_refs_json TEXT NOT NULL,effective_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',evidence_reference TEXT,evidence_sha256 TEXT,decision_note TEXT,decision_evidence_reference TEXT,decision_evidence_sha256 TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL,submitted_by TEXT,submitted_at TEXT,approved_by TEXT,approved_at TEXT,published_by TEXT,published_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS policy_versions_policy_number_idx ON policy_versions(policy_id,version_number);
CREATE INDEX IF NOT EXISTS policy_versions_status_date_idx ON policy_versions(status,effective_date,updated_at);
CREATE TABLE IF NOT EXISTS policy_attestation_campaigns(id TEXT PRIMARY KEY NOT NULL,policy_id TEXT NOT NULL,version_id TEXT NOT NULL,name TEXT NOT NULL,audience TEXT NOT NULL,due_date TEXT NOT NULL,required_count INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_by TEXT NOT NULL,created_at TEXT NOT NULL,closed_by TEXT,closed_at TEXT);
CREATE INDEX IF NOT EXISTS policy_campaigns_status_due_idx ON policy_attestation_campaigns(status,due_date);
CREATE TABLE IF NOT EXISTS policy_attestations(id TEXT PRIMARY KEY NOT NULL,campaign_id TEXT NOT NULL,subject_email TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',note TEXT,content_sha256 TEXT,attested_at TEXT,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS policy_attestations_campaign_subject_idx ON policy_attestations(campaign_id,subject_email);
CREATE TABLE IF NOT EXISTS policy_exceptions(id TEXT PRIMARY KEY NOT NULL,policy_id TEXT NOT NULL,version_id TEXT NOT NULL,scope TEXT NOT NULL,rationale TEXT NOT NULL,compensating_control TEXT NOT NULL,owner TEXT NOT NULL,reviewer TEXT NOT NULL,expires_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',decision_note TEXT,evidence_reference TEXT,evidence_sha256 TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL,submitted_by TEXT,submitted_at TEXT,decided_by TEXT,decided_at TEXT,closed_by TEXT,closed_at TEXT);
CREATE INDEX IF NOT EXISTS policy_exceptions_status_expiry_idx ON policy_exceptions(status,expires_at);
CREATE TABLE IF NOT EXISTS policy_events(id TEXT PRIMARY KEY NOT NULL,policy_id TEXT,version_id TEXT,campaign_id TEXT,exception_id TEXT,action TEXT NOT NULL,detail TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS policy_events_policy_date_idx ON policy_events(policy_id,created_at);
